\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $S=k[x_1,\ldots,x_n]$, let $F=(f_1,\ldots,f_r)$ be a homogeneous regular sequence with $2\leq e_1\leq\cdots\leq e_r$, and let $P=(x_1^{e_1},\ldots,x_r^{e_r})$. For every homogeneous ideal $I\supseteq F$, does there exist a unique lex-plus-$P$ ideal $L$ with the same Hilbert function, with $b_{i,j}(S/L)\geq b_{i,j}(S/I)$ for all $i,j$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2009/22}{[S2]}.

\subsection{Short English statement}
Let $S=k[x_1,\ldots,x_n]$, let $F=(f_1,\ldots,f_r)$ be a homogeneous regular sequence with $2\leq e_1\leq\cdots\leq e_r$, and let $P=(x_1^{e_1},\ldots,x_r^{e_r})$. For every homogeneous ideal $I\supseteq F$, does there exist a unique lex-plus-$P$ ideal $L$ with the same Hilbert function, with $b_{i,j}(S/L)\geq b_{i,j}(S/I)$ for all $i,j$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30001235 (OWR-3472-002). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2009/22}.
\end{itemize}
\label{end:30001235}

